const assets={"/app.js":{"type":"text/javascript; charset=utf-8","body":""},"/catalog-api.js":{"type":"text/javascript; charset=utf-8","body":""},"/catalog.js":{"type":"text/javascript; charset=utf-8","body":""},"/index.html":{"type":"text/html; charset=utf-8","body":""},"/legacy.js":{"type":"text/javascript; charset=utf-8","body":""},"/network-api.js":{"type":"text/javascript; charset=utf-8","body":""},"/network.js":{"type":"text/javascript; charset=utf-8","body":""},"/posters/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg":{"type":"image/jpeg","body":""},"/posters/2zmTngn1tYC1AvfnrFLhxeD82hz.jpg":{"type":"image/jpeg","body":""},"/posters/9PFonBhy4cQy7Jz20NpMygczOkv.jpg":{"type":"image/jpeg","body":""},"/posters/dDlEmu3EZ0Pgg93K2SVNLCjCSvE.jpg":{"type":"image/jpeg","body":""},"/posters/dMOpdkrDC5dQxqNydgKxXjBKyAc.jpg":{"type":"image/jpeg","body":""},"/posters/fleabag.svg":{"type":"image/svg+xml","body":""},"/posters/friends.jpg":{"type":"image/jpeg","body":""},"/posters/hm58Jw4Lw8OIeECIq5qyPYhAeRJ.jpg":{"type":"image/jpeg","body":""},"/posters/kEl2t3OhXc3Zb9FBh1AuYzRTgZp.jpg":{"type":"image/jpeg","body":""},"/posters/mYLOqiStMxDK3fYZFirgrMt8z5d.jpg":{"type":"image/jpeg","body":""},"/posters/sWgBv7LV2PRoQgkxwlibdGXKz1S.jpg":{"type":"image/jpeg","body":""},"/posters/uOOtwVbSr4QDjAGIifLDwpb2Pdl.jpg":{"type":"image/jpeg","body":""},"/posters/zU0htwkhNvBQdVSIKB9s6hgVeFK.jpg":{"type":"image/jpeg","body":""},"/style.css":{"type":"text/css; charset=utf-8","body":""}};
const PROVIDERS={all:null,Netflix:['nfx'],'Prime Video':['prv','amp'],'Disney+':['dnp']};
const fields=`id objectType content(country:$country,language:zh) {title originalTitle originalReleaseYear posterUrl shortDescription fullPath} offers(country:$country,platform:WEB) {standardWebURL monetizationType package {clearName shortName}}`;
const CATALOG_QUERY=`query Catalogue($country:Country!,$movie:TitleFilter!,$show:TitleFilter!){
 movies:popularTitles(country:$country,first:100,sortBy:POPULAR,filter:$movie){edges{node{${fields}}}}
 shows:popularTitles(country:$country,first:100,sortBy:POPULAR,filter:$show){edges{node{${fields}}}}
 trendingMovies:popularTitles(country:$country,first:24,sortBy:TRENDING,filter:$movie){edges{node{${fields}}}}
 trendingShows:popularTitles(country:$country,first:24,sortBy:TRENDING,filter:$show){edges{node{${fields}}}}
}`;
function parseParams(url){const country=(url.searchParams.get('country')||'TW').toUpperCase(),provider=url.searchParams.get('provider')||'all',q=(url.searchParams.get('q')||'').trim();if(!/^[A-Z]{2}$/.test(country)||!Object.hasOwn(PROVIDERS,provider)||q.length>100)throw Error('無效的查詢條件');return {country,provider,q};}
function providerName(p){const n=p?.shortName;if(n==='nfx'||/^netflix/i.test(p?.clearName||''))return 'Netflix';if((n==='amp'||n==='prv')||/amazon prime video/i.test(p?.clearName||''))return 'Prime Video';if(n==='dnp'||/^disney\+/i.test(p?.clearName||''))return 'Disney+';return null;}
function safeOfferURL(value,provider){try{const u=new URL(value);if(u.protocol!=='https:')return null;const host=u.hostname.toLowerCase();const matches=domain=>host===domain||host.endsWith('.'+domain);const allowed=provider==='Netflix'?matches('netflix.com'):provider==='Disney+'?matches('disneyplus.com'):matches('primevideo.com')||['amazon.com','amazon.co.uk','amazon.de','amazon.co.jp','amazon.fr','amazon.it','amazon.es','amazon.com.au','amazon.ca'].some(matches);return allowed?u.href:null;}catch{return null;}}
function normalize(node,country){const c=node.content||{};const offers=[];for(const o of node.offers||[]){if(o.monetizationType!=='FLATRATE')continue;const provider=providerName(o.package),url=safeOfferURL(o.standardWebURL,provider);if(provider&&url&&!offers.some(x=>x.provider===provider))offers.push({provider,url});}return {id:node.id,title:c.title||c.originalTitle||'未命名作品',en:c.originalTitle||'',year:c.originalReleaseYear||null,type:node.objectType==='MOVIE'?'movie':'drama',poster:c.posterUrl?'https://images.justwatch.com'+c.posterUrl.replace('{profile}','s332').replace('{format}','webp'):null,desc:c.shortDescription||'目前沒有簡介。',sourceURL:typeof c.fullPath==='string'&&c.fullPath.startsWith('/')?'https://www.justwatch.com'+c.fullPath:'https://www.justwatch.com/',offers,country};}
async function fetchCatalogue(params,fetcher=fetch){const {country,provider,q}=params;const filter={...(PROVIDERS[provider]?{packages:PROVIDERS[provider]}:{}),...(q?{searchQuery:q}:{})};const response=await fetcher('https://apis.justwatch.com/graphql',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({query:CATALOG_QUERY,variables:{country,movie:{...filter,objectTypes:['MOVIE']},show:{...filter,objectTypes:['SHOW']}}}),signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('榜單來源暫時無法連線');const body=await response.json();if(body.errors?.length||!body.data)throw Error('這個地區的榜單暫時無法取得，請重試或手動選擇地區');const result={country,provider,q,fetchedAt:new Date().toISOString(),source:'JustWatch',sourceURL:'https://www.justwatch.com/'+(country==='GB'?'uk':country.toLowerCase())};for(const key of ['movies','shows','trendingMovies','trendingShows']){const seen=new Set();result[key]=(body.data[key]?.edges||[]).map((e,index)=>({...normalize(e.node,country),rank:index+1})).filter(f=>!seen.has(f.id)&&seen.add(f.id));}return result;}

const json=(body,status=200,extra={})=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json; charset=utf-8',...extra}});
export default {
 async fetch(request,env,ctx){
  const url=new URL(request.url);
  if(!['GET','HEAD'].includes(request.method))return json({error:'Method not allowed'},405);
  if(url.pathname==='/api/catalog'){
   try{
    let params;
    try{params=parseParams(url);}catch(e){return json({error:e.message},400);}
    // Sites does not allow caches.default. Cache successful responses in the browser only.
    const result=await fetchCatalogue(params);
    console.info(JSON.stringify({event:'catalogue_loaded',country:params.country,provider:params.provider,movies:result.movies.length,shows:result.shows.length}));
    return json(result,200,{'cache-control':'private, max-age=900'});
   }catch(e){
    console.error(JSON.stringify({event:'catalogue_fetch_failed',country:url.searchParams.get('country'),error:e.message}));
    return json({error:e.message||'無法讀取榜單，請稍後重試。'},502,{'cache-control':'no-store'});
   }
  }
  const path=url.pathname==='/'?'/index.html':url.pathname;
  const asset=assets[path];
  if(!asset)return new Response('Not found',{status:404});
  const bytes=Uint8Array.from(atob(asset.body),c=>c.charCodeAt(0));
  return new Response(request.method==='HEAD'?null:bytes,{headers:{'content-type':asset.type,'cache-control':'no-cache','x-content-type-options':'nosniff'}});
 }
};
